// ManyChat's External Request action posts a JSON body here.
// Field names below match a typical ManyChat External Request setup;
// adjust the body.<field> names if you name your ManyChat fields differently.
const body = $json.body || {};

return [{
  json: {
    keyword: (body.keyword || '').toString().trim(),
    trigger: body.trigger || 'dm',
    platform: body.platform || 'instagram',
    name: body.name || body.full_name || '',
    contact: body.contact || body.email || body.phone || '',
    post_id: body.post_id || '',
    manychat_subscriber_id: body.subscriber_id || body.manychat_subscriber_id || ''
  }
}];
